GS.on('cityState', msg => {
  fecharQuadrosFlutuantes();
  _limparMortesVisuais();
  _hpSnapshot.clear();   // de volta à cidade: zera HP base p/ a próxima masmorra
  _limparPositiveEffectSnapshot();
  // Não limpe a fila em toda atualização da cidade: ao equipar um item
  // amaldiçoado, o servidor envia curse_result e logo depois city_state. A
  // limpeza incondicional descartava o aviso antes de ele aparecer. Só há uma
  // fila antiga para descartar quando estamos realmente deixando a masmorra.
  const vindoDaMasmorra = document.getElementById('screen-game')?.classList.contains('active');
  if(vindoDaMasmorra) _resetTrapPopup();
  // If returning from dungeon to city, tear down the 3D renderer first
  if(g3){ dispose3D(); mode3D = false; }
  // Ensure city screen is visible (covers both initial arrival and return from dungeon)
  showScreen('screen-city');
  handleCityState(msg);
  _renderAtalhos();
  _renderEfeitosAtivos(null);
  _atualizarMenuMagiasSeAberto();
  _refreshTurnTimerOption();
  _renderBannerForaMasmorra();
  // ── Sincroniza o herói do overlay com o estado autoritativo do servidor ──
  const meSrv = (msg.players || []).find(p => p.id === GS.myPid);
  if(meSrv) _sincronizarHeroiComServidor(meSrv);
  // Compra concluída → reabre a loja já com saldo/inventário atualizados.
  if(window._comprando && window._lojaUltimaAberta){
    window._comprando = false;
    abrirLoja(window._lojaUltimaAberta, GS.getHeroiAtivo());
  }
  // Painel da ficha aberto → re-renderiza com o estado novo (equipar/reordenar).
  if(_fcPanelPid != null) _refreshFichaCidadePanel();
  if(typeof InventoryModal !== 'undefined') InventoryModal.refresh();
  // Painel da Guilda aberto → re-renderiza (compra recém-concluída atualiza saldo/estado).
  const _gm = $('guild-modal');
  if(_gm && _gm.classList.contains('open')) _renderGuild();
});
// `isOpen()` também é verdadeiro com o inventário NORMAL aberto — usar ele aqui
// engolia o estado do Refúgio (o `updateStorage` não faz nada fora do modo baú)
// e o painel nunca aparecia. O que importa é qual BAÚ está aberto.
function _recebeuEstadoRefugio(scope, msg, renderPainel){
  if(scope === 'shared') _refugioState = msg;
  const modal = (typeof InventoryModal !== 'undefined') ? InventoryModal : null;
  if(modal && modal.storageScope() === scope){ modal.updateStorage(scope, msg); return; }
  // Baú de OUTRO herói não abre a janela dividida: o servidor não manda os itens.
  if(modal && _bauDireto === scope && (scope !== 'room' || msg.can_edit)){
    _bauDireto = null; _fecharRefugio(); modal.openStorage(scope, msg); return;
  }
  _bauDireto = null;
  renderPainel(msg);
}
GS.on('refugioState', msg => _recebeuEstadoRefugio('shared', msg, _renderRefugioPainel));
GS.on('quartoState',  msg => _recebeuEstadoRefugio('room',  msg, _renderQuartoPainel));

