GS.on('enterDungeon', (msg) => {
  fecharFichaCidade();
  _limparMortesVisuais();
  // O mapa-múndi é um overlay sobre screen-city e só some quando a cidade MUDA.
  // Entrar numa aventura não muda a cidade, então sem isto o jogador voltaria da
  // masmorra para o mapa-múndi em vez da ilustração da cidade.
  hideWorldMap();
  // O quadro de entrada de masmorra é anexado direto no body (position:fixed,
  // inset:0, z-index:60) — destroyCityImage()/showScreen() não o alcançam, e
  // sem removê-lo aqui ele fica cobrindo a masmorra e engolindo todo clique.
  _fecharEntradaMasmorra();
  _hpSnapshot.clear();   // novo cenário: zera HP base (1º game_state não dispara som)
  _resetTrapPopup();     // masmorra nova: descarta popup/fila de armadilha da anterior
  if(CITY_MODE==='image') destroyCityImage(); else destroyCity3D();
  // Tear down any leftover dungeon renderer from a previous run so the fresh
  // game_state rebuilds the scene from the correct (new) map. Combined with
  // gameState=null (gameState.js), this eliminates the "stale map / black
  // screen" bug on the 2nd+ dungeon entry.
  if(g3) dispose3D();
  mode3D = false;
  showScreen('screen-game');
  // Auto-enable 3D when entering the dungeon (if Three.js is available).
  // gameState foi limpo no enter_dungeon → init3D aguarda o estado fresco.
  if(window.THREE) toggle3D();
  // A transição começa a partir do evento autoritativo. Assim todos os
  // clientes veem a mesma tela e o servidor mantém a iniciativa bloqueada
  // durante todo o período informado.
  if(msg && msg.intro){
    const remaining=msg.intro_until_ms
      ? Math.max(0, Number(msg.intro_until_ms)-Date.now())
      : Number(msg.intro_duration_ms || 3000);
    _showCityTravelTransition(
      {transition_images:Array.isArray(msg.transition_images) ? msg.transition_images : []},
      {nome:'Masmorra'},
      remaining || Number(msg.intro_duration_ms || 3000));
  }
});

// Atalho de teclado "I" — abre/fecha o Inventário (Diablo-style modal).
document.addEventListener('keydown', (e) => {
  if(e.key !== 'i' && e.key !== 'I') return;
  const tag = (document.activeElement && document.activeElement.tagName) || '';
  if(tag === 'INPUT' || tag === 'TEXTAREA') return;
  if(!GS.myPid) return;
  const emRefugio = !!(document.getElementById('refugio-overlay') || document.getElementById('quarto-overlay'));
  if(!document.getElementById('screen-city')?.classList.contains('active') &&
     !document.getElementById('screen-game')?.classList.contains('active') && !emRefugio) return;
  InventoryModal.toggle(GS.myPid);
});

