// Números 1–9 e 0 ativam o slot correspondente mesmo com outros menus abertos.
document.addEventListener('keydown', e => {
  const tag = (document.activeElement && document.activeElement.tagName) || '';
  if(tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'CONTENTEDITABLE') return;
  const code = e.code || '';
  let index = -1;
  if(/^Digit[0-9]$/.test(code)) index = code === 'Digit0' ? 9 : Number(code.slice(-1)) - 1;
  else if(/^Numpad[0-9]$/.test(code)) index = code === 'Numpad0' ? 9 : Number(code.slice(-1)) - 1;
  if(index < 0 || !_atalhosDisponiveis()) return;
  const slots = GS.me?.shortcut_slots || [];
  if(!slots[index]) return;
  e.preventDefault(); e.stopImmediatePropagation();
  _ativarAtalho(slots[index], index);
}, true);

// #ficha-fab nasce dentro do markup de #screen-game, mas o Mapa de CR do mestre
// precisa permanecer acima da interface da masmorra. Por isso ele é movido para
// o <body>; para heróis, fica oculto (o inventário está no menu de personagem).
(function _fichaFabSempreVisivel(){
  const fab = document.getElementById('ficha-fab');
  if(fab) document.body.appendChild(fab);
})();

// Camada C: o botão flutuante é exclusivo do mestre e abre o Mapa de CR.
function _atualizarFichaFab(){
  const fab = document.getElementById('ficha-fab');
  if(!fab) return;
  if(GS.isMaster()){
    fab.style.display = document.getElementById('screen-game')?.classList.contains('active') ? 'flex' : 'none';
    fab.textContent = '🗺️';
    fab.title = 'Mapa de CR (mestre)';
    fab.onclick = () => abrirMinimapaCR();
  } else {
    fab.style.display = 'none';
  }
}

// O medidor fica gravado no localStorage: se estava ligado, recria a caixinha
// no boot (ela e criada sob demanda por _setFpsMostrar, nao existe no HTML).
if(_fpsMostrar) _setFpsMostrar(true);

GS.on('gameState', msg => {
  if(window._modoInstrumento && !GS.pendingInstrumento) _encerrarMiraInstrumento();
  _capturarDerrotasERessurreicoes(msg);
  _capturarMortesVisuais(msg);
  _capturarPositiveEffectChanges(msg);
  _detectHpChanges(msg);   // som de dano/cura por variação de HP entre estados
  _consumeResistanceEvents(msg);
  handleGameState(msg);
  _garantirLoopBolaFogo();  // mantém as chamas residuais pulsando até a zona expirar
  _garantirLoopRaioGelo();  // mantém a camada de gelo enquanto a paralisia existir
  _garantirLoopJatoAr();     // mantém o cone visível até o impacto terminar
  _garantirLoopMantoEscuridao(); // mantém a névoa pulsando enquanto a zona existir
  _atualizarMenuMagiasSeAberto();
  _refreshTurnTimerOption();
  _atualizarFichaFab();    // mantém o Mapa de CR disponível apenas ao mestre
  // Sincroniza os animados autoritativos do servidor no registro do Pedro,
  // para a ficha refletir HP/pó durante o combate.
  const meNow = (msg.players||[]).find(p => p.id === GS.myPid);
  if (meNow && Array.isArray(meNow.animados)) {
    HERO_DATA.pedro.animados = meNow.animados;
    if (GS.HERO_DATA && GS.HERO_DATA.pedro) GS.HERO_DATA.pedro.animados = meNow.animados;
  }
  // Entrou na minha janela de controle (servos e/ou prisioneiro) → dica única.
  if (msg.animados_turn === GS.myPid && _lastAnimadosTurn !== GS.myPid) {
    const meusAnimados = (msg.players.find(p=>p.id===GS.myPid)?.animados || [])
      .filter(a => a.vida_atual > 0 && !a.dominado_por_monstro);
    const porId = new Map(meusAnimados.map(a => [a.id, a]));
    const ordem = (msg.animados_order || []).map(id => porId.get(id)).filter(Boolean);
    const proximo = (ordem.length ? ordem : meusAnimados.sort((a, b) =>
      (b.initiative || 0) - (a.initiative || 0))).find(a => !a.acted) || null;
    _animadoSel = proximo ? proximo.id : null;
    _prisSel = false;
    const _pr = msg.prisoner;
    const soPris = _pr && _pr.alive && _pr.freed && _pr.rescuer_pid === GS.myPid
      && !((msg.players.find(p=>p.id===GS.myPid)?.animados||[]).some(a=>a.vida_atual>0));
    toast(soPris
      ? t('ui.hud.mova_prisioneiro')
      : t('ui.animar.turno_servos') + (proximo ? ' ' + t('ui.animar.servo_selecionado', {nome:proximo.nome}) : ''));
    if (mode3D && g3) renderMap3D(msg); else renderMap(msg);
  }
  // Janela de controle encerrou → limpa seleções.
  if (_lastAnimadosTurn === GS.myPid && msg.animados_turn !== GS.myPid) {
    _animadoSel = null;
    _prisSel = false;
  }
  _lastAnimadosTurn = msg.animados_turn || null;
  // Auto-refresh open chest window (contents may have changed)
  if(_openChestId){
    const updatedChest = (msg.chests||[]).find(c=>c.id===_openChestId);
    // A confirmação autoritativa chegou: volta a usar somente o conteúdo vindo
    // do servidor, que já não contém o item retirado.
    if(_pendingChestTake?.chestId === _openChestId){
      _ajustarFilaBaúApósRetirada(_pendingChestTake);
      clearPendingChestTake();
    }
    if(updatedChest) _renderChestWindow(updatedChest);
    else closeChestWindow();   // chest was emptied and removed
  }
  // Close decor loot panel if the decoration is now empty or gone
  if(_openDecorLootId){
    const decor = (msg.decorations||[]).find(d=>d.id===_openDecorLootId);
    if(!decor || !decor.tem_loot) closeChestWindow();
  }
});

GS.on('gmNarration', text => appendGM(text));

// ── Falas de NPC (Modo Mestre): balão leve, distinto do log e da story ──
let _falaFila = [];
let _falaTimer = null;
function _mostrarProximaFala(){
  const host = $('fala-popup');
  if(!host) return;
  if(!_falaFila.length){ host.classList.remove('open'); return; }
  const f = _falaFila.shift();
  const emoji = (f.falante && f.falante.emoji) || '💬';
  const nome  = (f.falante && f.falante.nome)  || '';
  host.innerHTML = `<div class="fala-emoji">${_esc(emoji)}</div>` +
    `<div class="fala-corpo">${nome ? `<div class="fala-nome">${_esc(nome)}</div>` : ''}` +
    `<div class="fala-texto">${_esc(f.texto || '')}</div></div>`;
  host.classList.add('open');
  if(_falaTimer) clearTimeout(_falaTimer);
  _falaTimer = setTimeout(_mostrarProximaFala, 5000);
}
function _avancarFala(){ if(_falaTimer) clearTimeout(_falaTimer); _mostrarProximaFala(); }
GS.on('fala', msg => { _falaFila.push(msg); if(!$('fala-popup').classList.contains('open')) _mostrarProximaFala(); });

