// ── Overlay de seleção das 2 magias iniciais (criação, Pedro/Lewis) ───────────
function mostrarOverlaySelecaoMagiasCriacao(cls){
  window._magiasCriacaoSel = [];
  window._magiasCriacaoCls = cls;
  const existente = document.getElementById('overlay-selecao-criacao');
  if (existente) existente.remove();
  const el = document.createElement('div');
  el.id = 'overlay-selecao-criacao';
  el.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.88); z-index:9999; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:16px;';
  document.body.appendChild(el);
  _renderOverlaySelecaoCriacao();
}

function _renderOverlaySelecaoCriacao(){
  const el = document.getElementById('overlay-selecao-criacao');
  if(!el) return;
  const cls = window._magiasCriacaoCls;
  const sel = window._magiasCriacaoSel || [];
  const opcoes = Object.values(GRIMORIO_CLIENT).filter(m => m.circulo === 'primeiro' && m.classe.includes(cls));
  const cartas = opcoes.map(m => {
    const on = sel.includes(m.id);
    return `
      <div onclick="window._toggleMagiaCriacao('${m.id}')"
           onmouseenter="mostrarTooltipMagia('${m.id}', event)"
           onmouseleave="ocultarTooltipMagia()"
           style="position:relative; display:inline-block; overflow:hidden;
                  width:74px; height:88px; cursor:pointer; margin:5px; border-radius:4px;
                  background:${on ? 'rgba(200,169,81,0.18)' : 'rgba(255,255,255,0.04)'};
                  border:2px solid ${on ? '#c8a951' : '#c8a95155'}; transition:all 0.2s;">
        <div style="position:absolute; inset:0; display:flex; align-items:center; justify-content:center; font-size:40px; line-height:1;">${magiaIconFill(m)}</div>
        ${on ? `<div style="position:absolute; bottom:3px; left:50%; transform:translateX(-50%); width:8px; height:8px; border-radius:50%; background:#c8a951; z-index:2; box-shadow:0 0 3px rgba(0,0,0,0.85);"></div>` : ''}
      </div>`;
  }).join('');
  const pronto = sel.length === 2;
  el.innerHTML = `
    <div style="color:#c8a951; font-family:'Cinzel Decorative',serif; font-size:15px; letter-spacing:3px; text-align:center;">${t('ui.magia.magias_iniciais')}<br><span style="font-size:11px; color:#8a7a5a; letter-spacing:2px;">${t('ui.selecao.escolha_2_magias')}</span></div>
    <div style="display:flex; flex-wrap:wrap; gap:6px; max-width:680px; justify-content:center;">${cartas}</div>
    <div style="color:${pronto ? '#44cc88' : '#8a7a5a'}; font-size:11px; letter-spacing:1px;">${t('ui.magia.n_selecionadas', {n:sel.length, max:2})}</div>
    <button onclick="window._confirmarMagiasCriacao()" ${pronto ? '' : 'disabled'}
      style="padding:9px 22px; font-family:'Cinzel',serif; font-size:11px; letter-spacing:2px;
             background:${pronto ? 'rgba(68,204,136,0.18)' : 'rgba(80,80,80,0.18)'};
             color:${pronto ? '#44cc88' : '#666'}; border:1px solid ${pronto ? '#44cc88' : '#444'};
             cursor:${pronto ? 'pointer' : 'not-allowed'};">${t('ui.geral.confirmar')}</button>`;
}

window._toggleMagiaCriacao = function(id){
  const sel = window._magiasCriacaoSel || (window._magiasCriacaoSel = []);
  const i = sel.indexOf(id);
  if(i >= 0) sel.splice(i,1);
  else if(sel.length < 2) sel.push(id);
  _renderOverlaySelecaoCriacao();
};

window._confirmarMagiasCriacao = function(){
  const sel = window._magiasCriacaoSel || [];
  if(sel.length !== 2){ toast(t('ui.selecao.escolha_2_magias'), 'var(--orange)'); return; }
  GS.setKnownSpells(sel);
  const el = document.getElementById('overlay-selecao-criacao');
  if (el) el.remove();
  toast('Magias escolhidas!', 'var(--gold)');
};

// Esc abre o menu somente quando nenhuma interface contextual está usando a
// tecla para cancelar/fechar uma ação. Os demais listeners registram-se antes
// deste e marcam o evento como preventDefault quando o consomem.
document.addEventListener('keydown', e => {
  if(e.key !== 'Escape') return;
  // Esc agora abre/fecha o painel ⚙️ unificado (config + Voltar ao início/Sair).
  const pop = document.getElementById('audio-pop');
  if(pop && pop.style.display !== 'none'){
    _toggleConfigPop(false);
    e.preventDefault();
    return;
  }
  // Alguns modos de mira registram seus próprios handlers dinamicamente. Esperar
  // o fim da propagação permite que eles consumam Esc antes de abrir o menu.
  setTimeout(() => {
    if(e.defaultPrevented) return;
    if(document.querySelector('#target-modal.open, #chest-overlay.open, #trap-overlay.open, #shop-modal.open, .guild-modal.open, #menu-status-overlay.open, #overlay-selecao-criacao, #loja-overlay, #ficha-overlay-jogo')) return;
    if(GS.pendingSkill || GS.pendingThrow || GS.pendingAction || window._modoImplantarReforco) return;
    const active = document.querySelector('.screen.active');
    if(!active || !['screen-game', 'screen-city', 'screen-class-select'].includes(active.id)) return;
    _toggleConfigPop(true);
  }, 0);
});

document.getElementById('pause-menu')?.addEventListener('click', e => {
  if(e.target === e.currentTarget) togglePauseMenu(false);
});

// ── Modo prévia do editor (index.html?preview=1) ─────────────────────────────
// Sem login, sem lobby e sem socket: o editor injeta um game_state por
// postMessage e o renderer 3D normal desenha a masmorra. Como é o MESMO
// renderer do jogo, a prévia não pode divergir do que o jogador vai ver.
if(GS.isPreview){
  document.body.classList.add('preview-mode');
  showScreen('screen-game');
  // Mesmo caminho de entrada na masmorra (GS.on('enterDungeon')): toggle3D faz
  // mais do que ligar a flag — esconde o canvas 2D e prepara os controles.
  if(window.THREE) toggle3D();
  window.addEventListener('message', ev => {
    const d = ev.data;
    if(!d || d.type !== 'preview_state' || !d.state) return;
    GS.injectPreviewState(d.state);
    // O jogo recebe um game_state a cada ação; a prévia recebe UM só. Quem
    // posiciona, escala e mostra os meshes que chegam depois (GLB de objeto,
    // modelo de monstro, miniatura extrudada) é o renderMap3D — que sem estes
    // passes extras rodaria só uma vez, antes de os arquivos carregarem, e o
    // objeto ficaria fora do lugar, sem o vscale ou invisível.
    [250, 800, 2000, 4000].forEach(ms => setTimeout(() => {
      if(GS.gameState) renderMap(GS.gameState);
      _preview_reportarModelos();
    }, ms));
  });
  // O editor só manda o estado depois deste aviso: antes disso a tela do jogo
  // ainda não existe e o init3D não teria onde desenhar.
  try { window.parent.postMessage({ type: 'preview_ready' }, '*'); } catch(e) {}
}

// Diz ao editor qual arte 3D cada objeto e cada monstro resolveu, usando as
// MESMAS tabelas que o renderer consulta. Sem isto a resolução é invisível: um
// modelo que não existe, ou um tipo sem entrada na tabela, some do mapa sem
// explicação e o autor não tem como saber se o problema é dele ou do arquivo.
function _preview_reportarModelos(){
  const { objetos, monstros } = _relatorioArte3D();
  if(!objetos && !monstros) return;
  try { window.parent.postMessage({ type: 'preview_modelos', objetos, monstros }, '*'); } catch(e) {}
}

// ── Relatório de arte 3D (fonte única) ───────────────────────────────────────
// Resolve, para cada monstro e cada objeto do estado atual, QUAL arte o renderer
// vai usar e em que pé ela está. Usa exatamente as mesmas tabelas e caches do
// renderer — se divergisse, o relatório mentiria justamente quando fosse útil.
// Consumido pela prévia do editor e pelo painel de diagnóstico do modo teste.
function _relatorioArte3D(){
  const st = GS.gameState;
  if(!st) return { objetos: null, monstros: null };

  const estadoGLB = (caminho, cache) => {
    if(!caminho) return null;
    const c = cache[caminho];
    const estado = c === 'erro' ? 'erro' : (c ? 'carregado' : 'carregando');
    const out = { tipo: 'GLB', caminho, estado };
    if(estado === 'erro') out.motivo = _glbErroMsg[caminho] || 'erro desconhecido';
    return out;
  };
  // Billboard PNG: o estado mora no cache de texturas, não no de GLB.
  const estadoPNG = (caminho, cacheKey) => {
    if(_pawnTexErro[cacheKey]) return { tipo: 'PNG', caminho, estado: 'erro',
                                        motivo: t('ui.diag.arquivo_nao_carregou') };
    const tex = _pawnTexCache[cacheKey];
    const pronta = !!(tex && tex.image && tex.image.width);
    return { tipo: 'PNG', caminho, estado: pronta ? 'carregado' : 'carregando' };
  };

  const objetos = (st.decorations || []).map(d => {
    const glb = d.model3d || (d.image && DECOR_GLB_MODELS[d.image]) || DECOR_GLB_TYPES[d.type];
    const arte = estadoGLB(glb, _decorGLBCache);
    // GLB ausente OU com erro → o renderer cai na miniatura extrudada do PNG.
    if(!arte || arte.estado === 'erro'){
      const img = d.image ? _objImg3D[d.image] : null;
      const alt = d.image
        ? { tipo: 'PNG', caminho: `assets/objetos/${d.image}`,
            estado: (img && img.complete && img.naturalWidth) ? 'carregado' : 'carregando' }
        : { tipo: 'procedural', caminho: null, estado: 'ok' };
      return { nome: d.type, pos: d.pos, emoji: d.emoji || '📦', arte: arte || alt,
               emUso: arte ? alt : null };
    }
    return { nome: d.type, pos: d.pos, emoji: d.emoji || '📦', arte };
  });

  const monstros = (st.monsters || []).map(m => {
    const imageName = _monsterImageName(m);
    const arte = estadoGLB(m.model3d || _monsterGLBPath(imageName, m.type), _monsterGLBCache);
    if(!arte || arte.estado === 'erro'){
      const alt = imageName
        ? estadoPNG(`assets/pawns/monstros/${imageName}/${imageName}.png`, '__mon_' + imageName)
        : { tipo: 'procedural', caminho: null, estado: 'ok' };
      return { nome: m.type, pos: m.pos, emoji: m.emoji || '👹', arte: arte || alt,
               emUso: arte ? alt : null };
    }
    return { nome: m.type, pos: m.pos, emoji: m.emoji || '👹', arte };
  });

  return { objetos, monstros };
}

// Texto puro do relatório — é isto que o autor copia e cola quando algo some do
// tabuleiro. Sem ele, "não apareceu" continua sendo um relato sem dado nenhum.
function _relatorioArte3DTexto(){
  const { objetos, monstros } = _relatorioArte3D();
  if(!objetos) return 'Sem masmorra carregada.';
  const linha = it => {
    const a = it.arte, u = it.emUso;
    const base = `${it.emoji} ${it.nome} @${(it.pos||[]).join(',')} — ${a.tipo}`
               + `${a.caminho ? ' ' + a.caminho : ''} [${a.estado}${a.motivo ? ': ' + a.motivo : ''}]`;
    return u ? `${base} → usando ${u.tipo}${u.caminho ? ' ' + u.caminho : ''} [${u.estado}]` : base;
  };
  const conta = arr => {
    const c = { GLB: 0, PNG: 0, procedural: 0, erro: 0 };
    for(const it of arr){ c[it.arte.tipo]++; if(it.arte.estado === 'erro') c.erro++; }
    return `${arr.length} itens — ${c.GLB} GLB, ${c.PNG} PNG, ${c.procedural} procedural, ${c.erro} com erro`;
  };
  return [
    t('ui.diag.titulo', {data:new Date().toLocaleString()}),
    `cliente: ${typeof _arteGen === 'number' ? 'atual' : 'ANTIGO (recarregue com Ctrl+Shift+R)'}`,
    ``, `MONSTROS (${conta(monstros)})`, ...monstros.map(linha),
    ``, `OBJETOS (${conta(objetos)})`, ...objetos.map(linha),
  ].join('\n');
}

function fecharDiagnosticoArte3D(){ document.getElementById('diag-arte3d')?.remove(); }

// Painel só-mestre do modo teste: mostra, item a item, qual arte o renderer
// escolheu e se ela carregou. É a resposta direta para "o monstro virou um peão
// genérico" / "o objeto não apareceu" — sem precisar abrir o console.
function abrirDiagnosticoArte3D(){
  fecharDiagnosticoArte3D();
  const { objetos, monstros } = _relatorioArte3D();
  if(!objetos){ toast('Nenhuma masmorra carregada.', 'var(--gold)'); return; }
  const cor = e => e === 'erro' ? '#ff6b6b' : e === 'carregando' ? '#ffd166' : '#8ce99a';
  const linha = it => {
    const a = it.arte, u = it.emUso;
    return `<tr>
      <td style="padding:2px 6px">${it.emoji} ${_esc(it.nome)}</td>
      <td style="padding:2px 6px;opacity:.6">${(it.pos||[]).join(',')}</td>
      <td style="padding:2px 6px"><b>${a.tipo}</b></td>
      <td style="padding:2px 6px;opacity:.75;word-break:break-all">${_esc(a.caminho || '—')}</td>
      <td style="padding:2px 6px;color:${cor(a.estado)}">${a.estado}${a.motivo ? ' · ' + _esc(a.motivo) : ''}${
        u ? ` <span style="opacity:.6">→ usando ${u.tipo} [${u.estado}]</span>` : ''}</td>
    </tr>`;
  };
  const tabela = (titulo, arr) => `<h3 style="margin:10px 0 4px;font-size:.8rem;letter-spacing:.08em">${titulo} (${arr.length})</h3>`
    + `<table style="width:100%;border-collapse:collapse;font-size:.68rem">${arr.map(linha).join('')}</table>`;
  const el = document.createElement('div');
  el.id = 'diag-arte3d';
  el.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.72);'
                   + 'display:flex;align-items:center;justify-content:center';
  el.innerHTML = `<div style="background:#141420;border:1px solid #3a3a55;border-radius:10px;
      max-width:min(920px,92vw);max-height:84vh;overflow:auto;padding:14px 16px;color:#e8e8f0">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
      <b style="font-size:.9rem">${t('ui.diag.painel_titulo')}</b>
      <span style="flex:1"></span>
      <button id="diag-copiar" style="cursor:pointer">${t('ui.diag.copiar')}</button>
      <button id="diag-fechar" style="cursor:pointer">✕</button>
    </div>
    ${typeof _arteGen === 'number' ? '' :
      `<div style="color:#ff6b6b">${t('ui.diag.cliente_antigo')}</div>`}
    ${tabela('MONSTROS', monstros)}
    ${tabela('OBJETOS', objetos)}
  </div>`;
  el.onclick = e => { if(e.target === el) fecharDiagnosticoArte3D(); };
  document.body.appendChild(el);
  el.querySelector('#diag-fechar').onclick = fecharDiagnosticoArte3D;
  el.querySelector('#diag-copiar').onclick = () => {
    const txt = _relatorioArte3DTexto();
    navigator.clipboard?.writeText(txt).then(
      () => toast(t('ui.diag.relatorio_copiado'), 'var(--green)'),
      () => console.log(txt));
    console.log(txt);
  };
}
window.abrirDiagnosticoArte3D = abrirDiagnosticoArte3D;
window.fecharDiagnosticoArte3D = fecharDiagnosticoArte3D;
window.diagnosticoArte3D = () => { console.log(_relatorioArte3DTexto()); };
